  function renderExecutionEvents(result){const events=result.execution?.events||[],host=$('executionEvents'),key=result.task.id+'|'+JSON.stringify(events);if(host.dataset.events!==key){host.dataset.events=key;host.replaceChildren();if(!events.length){const empty=document.createElement('p');empty.className='muted';empty.textContent=result.execution?.error||'尚无工具执行记录。Agent 消息显示在上方对话中。';host.append(empty);}for(const event of events){const row=document.createElement('div'),badge=document.createElement('span'),text=document.createElement('span'),time=document.createElement('time');row.className='execution-event';badge.className='execution-event-status';badge.textContent=event.kind==='tool'?({pending:'待执行',in_progress:'执行中',completed:'已完成',failed:'失败'}[event.status]||'工具'):({permission:'授权',notice:'通知',error:'错误',turn:'轮次',plan:'计划'}[event.kind]||'事件');row.dataset.status=event.status||event.kind;text.textContent=event.text;time.textContent=formatTime(event.at);row.append(badge,text,time);host.append(row);}}$('executionTraceHint').textContent=result.execution?.hasEarlier?'· 最近 8 条摘要，完整过程见记录':'';$('fullExecution').disabled=!(result.task.stage==='worker'?result.sessions.worker:result.sessions.coordinator);$('fullExecution').onclick=function(){agentberth.openSession(result.task.stage==='worker'?result.task.workerSession:result.task.coordinatorSession)};}
